var n=`0098-verashchaka`;var a=`world-0098`;var t=`BY`;var s=`eastern-europe`;var r=4;var o=92;var l={en:`Verashchaka`,ua:`Верашчака`};var d={en:`A classic dish from Belarus, featuring pork ribs, yellow onion, garlic, rye bread. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Білорусь. Основні складники: свинячі ребра, жовта цибуля, часник, житній хліб. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 12 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 12 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:12,i:[[`pork-ribs`,800,`g`],[`lard`,35,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 8 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 8 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:8,i:[[`yellow-onion`,210,`g`],[`garlic`,3,`clove`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 70 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 70 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:70,i:[[`rye-bread`,180,`g`],[`water`,500,`ml`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,12,`g`]]}];var u={slug:n,id:a,country:`BY`,region:s,servings:4,minutes:92,title:l,text:d,steps:g};export{t as country,u as default,a as id,o as minutes,s as region,r as servings,n as slug,g as steps,d as text,l as title};